function medicine38Race(array $job):array {
    $path=__DIR__.'/.medicine38-validation';foreach(array_keys($job) as $actor){if(is_file($path.'/ready'.$actor)){unlink($path.'/ready'.$actor);}}if(is_file($path.'/go')){unlink($path.'/go');}file_put_contents($path.'/job.json',json_encode($job,JSON_THROW_ON_ERROR));$workers=[];
    foreach($job as $actor=>$command){$workers[$actor]=proc_open([PHP_BINARY,__FILE__,'worker',(string)$actor],[0=>['pipe','r'],1=>['file',$path.'/worker'.$actor.'.json','w'],2=>['file',$path.'/worker'.$actor.'.err','w']],$pipes);if(!is_resource($workers[$actor])){throw new RuntimeException('Race worker startup failed.');}fclose($pipes[0]);}
    $deadline=microtime(true)+15;while(true){$ready=true;foreach(array_keys($job) as $actor){$ready=$ready&&is_file($path.'/ready'.$actor);}if($ready){break;}if(microtime(true)>$deadline){throw new RuntimeException('Race barrier readiness timeout.');}usleep(10000);}file_put_contents($path.'/go','go');$results=[];foreach($workers as $actor=>$worker){medicineCheck(proc_close($worker)===0,'Race worker failed; inspect disposable diagnostics');$results[$actor]=json_decode(file_get_contents($path.'/worker'.$actor.'.json'),true,64,JSON_THROW_ON_ERROR);}return $results;
}
