foreach([['S','3','53'],['F','30','53']] as [$tag,$target,$ref]){medicineTest('real same-timestamp activity round trip and fresh recovery '.$tag,function()use($pdo,$repo,$service,$auth,$eligibility,$tag,$target,$ref){$before=$repo->latest('chemical',$ref);$input=medicineGovernanceInput($repo,$eligibility,'chemical',$ref,['rationale'=>'Stale decision','evidence'=>medicineSyntheticEvidence()]);medicine38Activity($pdo,['scope'=>$tag,'id'=>$target,'values'=>[0,1]]);medicineReject(fn()=>$eligibility->requireCurrent('chemical',$ref),409);$auth->actorId=2;medicineReject(fn()=>$service->verify('chemical',$ref,$input),409);medicineVerifyRef($repo,$service,$auth,$eligibility,$ref);$eligibility->requireCurrent('chemical',$ref);medicineCheck($repo->event((string)$before['id'])===$before);$column=$tag==='S'?'substance_id':'form_id';$q=$pdo->prepare('SELECT old_active,new_active,source,occurred_at FROM medicine_registry_lifecycle_events WHERE '.$column.'=? ORDER BY id');$q->execute([$target]);$events=$q->fetchAll();medicineCheck(count($events)===2&&$events[0]['old_active']==1&&$events[0]['new_active']==0&&$events[1]['new_active']==1&&$events[0]['source']==='registry_trigger'&&$events[0]['occurred_at']!=='');});}
medicineTest('lifecycle journal UPDATE DELETE and invalid writes rejected',function()use($pdo){medicine38SqlReject(fn()=>$pdo->exec('UPDATE medicine_registry_lifecycle_events SET new_active=1 WHERE id>0 LIMIT 1'),1644);medicine38SqlReject(fn()=>$pdo->exec('DELETE FROM medicine_registry_lifecycle_events WHERE id>0 LIMIT 1'),1644);medicine38SqlReject(fn()=>$pdo->exec("INSERT INTO medicine_registry_lifecycle_events(substance_id,old_active,new_active,source,occurred_at) VALUES(3,1,1,'registry_trigger',UTC_TIMESTAMP(6))"),4025);medicine38SqlReject(fn()=>$pdo->exec("INSERT INTO medicine_registry_lifecycle_events(substance_id,old_active,new_active,source,occurred_at) VALUES(3,1,0,'invented_user',UTC_TIMESTAMP(6))"),4025);medicine38SqlReject(fn()=>$pdo->exec("INSERT INTO medicine_registry_lifecycle_events(substance_id,old_active,new_active,occurred_at) VALUES(999999,1,0,UTC_TIMESTAMP(6))"),1452);});
medicineTest('registry invalidation versus review cannot retain old authority',function()use($repo,$eligibility){$input=medicineGovernanceInput($repo,$eligibility,'chemical','53',['rationale'=>'Concurrent review','evidence'=>medicineSyntheticEvidence()]);$results=medicine38Race([2=>['action'=>'review','scope'=>'chemical','id'=>'53','input'=>$input],6=>['action'=>'activity','scope'=>'F','id'=>'30','values'=>[0]]]);medicineCheck($results[6]['status']==='ok');medicineReject(fn()=>$eligibility->requireCurrent('chemical','53'),409);});
medicineTest('reactivation versus stale review requires fresh decision',function()use($repo,$eligibility,$pdo,$service,$auth){$old=$repo->latest('chemical','53');$snapshot=json_decode($old['snapshot_json'],true);$input=['expected_revision'=>$repo->target('chemical','53')['metadata_revision'],'expected_snapshot_hash'=>hash('sha256',$old['snapshot_json']),'rationale'=>'Stale restoration','evidence'=>medicineSyntheticEvidence()];$results=medicine38Race([2=>['action'=>'review','scope'=>'chemical','id'=>'53','input'=>$input],6=>['action'=>'activity','scope'=>'F','id'=>'30','values'=>[1]]]);medicineCheck($results[6]['status']==='ok'&&$results[2]['status']==='denied');medicineReject(fn()=>$eligibility->requireCurrent('chemical','53'),409);medicineVerifyRef($repo,$service,$auth,$eligibility,'53');$eligibility->requireCurrent('chemical','53');});
medicineTest('withdrawal versus invalidation protects all subsequent paths',function()use($repo,$eligibility,$pdo,$service,$auth){$auth->actorId=8;$service->grantAuthority(['user_id'=>6,'capability'=>'steward','scope'=>'chemical','expires_at'=>'2030-01-01 00:00:00.000001','rationale'=>'Synthetic lifecycle race']);$revision=$repo->target('chemical','53')['metadata_revision'];$results=medicine38Race([4=>['action'=>'invalidate','scope'=>'chemical','id'=>'53','input'=>['expected_revision'=>$revision,'state'=>'invalidated','rationale'=>'Concurrent invalidation']],6=>['action'=>'invalidate','scope'=>'chemical','id'=>'53','input'=>['expected_revision'=>$revision,'state'=>'withdrawn','rationale'=>'Concurrent withdrawal']]]);medicineCheck(count(array_filter($results,fn($r)=>$r['status']==='ok'))===1);$auth->actorId=4;if($repo->latest('chemical','53')['new_state']!=='withdrawn'){$service->invalidate('chemical','53',['expected_revision'=>$repo->target('chemical','53')['metadata_revision'],'state'=>'withdrawn','rationale'=>'Final protected state']);}$before=$pdo->query('SELECT COUNT(*) FROM medicine_governance_events')->fetchColumn();medicineReject(fn()=>$service->invalidate('chemical','53',['expected_revision'=>$repo->target('chemical','53')['metadata_revision'],'state'=>'invalidated','rationale'=>'Attempt bypass']),409);$auth->actorId=1;medicineReject(fn()=>$service->assessChemical('53',medicineGovernanceInput($repo,$eligibility,'chemical','53',['state'=>'candidate','rationale'=>'Attempt restore'])),409);medicineReject(fn()=>$eligibility->requireCurrent('chemical','53'),409);medicineCheck($before===$pdo->query('SELECT COUNT(*) FROM medicine_governance_events')->fetchColumn());});
medicineTest('stale review versus state reassessment cannot regain authority',function()use($repo,$service,$auth,$eligibility,$pdo){$auth->actorId=2;medicineReject(fn()=>$service->verify('chemical','53',['expected_revision'=>$repo->target('chemical','53')['metadata_revision'],'expected_snapshot_hash'=>str_repeat('0',64),'rationale'=>'Protected stale review','evidence'=>medicineSyntheticEvidence()]),409);$input=medicineGovernanceInput($repo,$eligibility,'chemical','53',['rationale'=>'Concurrent restoration']);$results=medicine38Race([2=>['action'=>'review','scope'=>'chemical','id'=>'53','input'=>$input+['evidence'=>medicineSyntheticEvidence()]],1=>['action'=>'assess','id'=>'53','input'=>$input+['state'=>'candidate']]]);medicineCheck($results[2]['status']==='denied'&&$results[1]['status']==='denied');medicineReject(fn()=>$eligibility->requireCurrent('chemical','53'),409);});
